
export class Transaction {
  constructor(sequelize: any, options: any);

  public commit(): Promise<void>;

  public rollback(): Promise<void>;

  public afterCommit(fn: (transaction: this) => void | Promise<void>): void;

  static get LOCK(): LOCK;

  get LOCK(): LOCK;
}

export namespace Transaction {
  enum ISOLATION_LEVELS {
    READ_UNCOMMITTED = 'READ UNCOMMITTED',
    READ_COMMITTED = 'READ COMMITTED',
    REPEATABLE_READ = 'REPEATABLE READ',
    SERIALIZABLE = 'SERIALIZABLE',
  }

  enum TYPES {
    DEFERRED = 'DEFERRED',
    IMMEDIATE = 'IMMEDIATE',
    EXCLUSIVE = 'EXCLUSIVE',
  }
}

export enum LOCK {
  UPDATE = 'UPDATE',
  SHARE = 'SHARE',
  KEY_SHARE = 'KEY SHARE',
  NO_KEY_UPDATE = 'NO KEY UPDATE',
}

interface LOCK {
  UPDATE: LOCK.UPDATE;
  SHARE: LOCK.SHARE;
  KEY_SHARE: LOCK.KEY_SHARE;
  NO_KEY_UPDATE: LOCK.NO_KEY_UPDATE;
}

export interface TransactionOptions  {
  autocommit?: boolean;
  isolationLevel?: Transaction.ISOLATION_LEVELS;
  type?: Transaction.TYPES;
  deferrable?: string | string;
  transaction?: Transaction | null;
}

export default Transaction;
